import {SECTORS,availableModules,terminalAvailable,nextTerminal,claimTerminal} from './engine.js';
import {TERMINAL_CASES,newTerminal,terminalCommand} from './terminal.js';
let lab=newTerminal(),labLog=['RESISTANCE RECOVERY CONSOLE / SIMULATED TERMINAL','Type help to see the commands. Start with your work order.'],labHistory=[],labHistoryAt=0,labState=null;
export function renderTerminalPanel(ctx){
const {state,save,toast,badges,updateHud,esc}=ctx,$=s=>document.querySelector(s);
if(labState!==state){labState=state;lab=newTerminal(nextTerminal(state)??0);labLog=['WORKSTATION RECOVERY / '+TERMINAL_CASES[lab.id].title,'Type help or read the recovery order.'];labHistory=[];labHistoryAt=0;}
if(!terminalAvailable(state,lab.id)||ctx.preferNext&&state.terminalCompleted.includes(lab.id)&&nextTerminal(state)!==undefined){lab=newTerminal(nextTerminal(state)??0);labLog=['WORKSTATION RECOVERY / '+TERMINAL_CASES[lab.id].title,'Type help or read the recovery order.'];}
const job=TERMINAL_CASES[lab.id],done=state.terminalCompleted.includes(lab.id);
$('#view').innerHTML=`<div class="section-intro"><div><p class="eyebrow">CAMPAIGN SUPPLY LINE</p><h2>Recovery terminal</h2><p>Each recovered server opens a supply cache: components for equipment and a working uplink module for your next site. Complete this sector’s recovery, then return to the network.</p></div><span class="chip" id="caseCount">${state.terminalCompleted.length}/6 cases solved</span></div><div class="two-col terminal-layout"><section class="panel pad"><div class="row"><label for="caseSelect" class="label">RECOVERY ORDER</label><select id="caseSelect" class="secondary">${TERMINAL_CASES.map((j,i)=>`<option value="${i}" ${i===lab.id?'selected':''} ${!terminalAvailable(state,i)?'disabled':''}>${i+1}. ${j.title}${state.terminalCompleted.includes(i)?' ✓':''}${!terminalAvailable(state,i)?' · requires '+SECTORS[i].name+(i?' and case '+i:''):''}</option>`).join('')}</select></div><p class="eyebrow" style="margin-top:20px">${job.tag}</p><h3>${job.title}</h3><p>${job.brief}</p><p class="small muted" id="caseReward">${done?'Cache recovered. Replay for practice.':`Recovered cache: ${job.reward} components + 1 intel + 1 uplink module.`}</p><div id="terminalLog" class="terminal terminal-live" role="log" aria-label="Terminal output" aria-live="polite"></div><form id="terminalForm" class="terminal-input-row"><label for="terminalCommand" id="terminalPrompt">${esc(lab.cwd)}&gt;</label><input id="terminalCommand" autocomplete="off" autocapitalize="off" spellcheck="false" maxlength="160" aria-label="Terminal command" placeholder="Type help"><button class="primary" type="submit">Run</button></form><div class="row" style="margin-top:12px"><button class="ghost" id="caseHint">Case hint</button><button class="ghost" id="resetCase">Restart this case</button></div><div id="caseFeedback" aria-live="polite"></div><button class="secondary" id="backToNetwork" style="margin-top:16px">Return to network · ${availableModules(state)} modules available</button></section><aside class="panel pad"><h3>Inspect. Repair. Verify.</h3><p class="muted">Use evidence from the terminal. A successful ping does not guarantee that DNS or a web service works.</p><div class="lesson"><p>${job.lesson}</p></div><h3>Command reference</h3><p class="small muted">These buttons put a command in the input. You decide when to run it.</p><div class="command-list">${job.commands.map(c=>`<button class="secondary" data-insert-command="${esc(c)}">${esc(c)}</button>`).join('')}<button class="secondary" data-insert-command="submit">submit</button><button class="secondary" data-insert-command="help">help</button></div><details><summary>What is real, and what is simulated?</summary><p>dir, cd, type, ipconfig, ping, tracert, route print, nslookup, and curl use Windows-style syntax. This sandbox implements a small teaching subset and generates fictional output.</p><p><code>repair</code>, <code>configure</code>, and <code>submit</code> are game-only actions, not operating-system commands. They change only this simulated lab. Nothing here reads your computer, launches a shell, or contacts a real network.</p><p>The lab uses 192.168.1.0/24, the fictional name portal.test, and documentation address 198.51.100.20.</p></details><details><summary>More cases</summary><p>One recovery opens in each sector after the previous case is completed. Casebooks are free. The six recoveries supply five new sites and the final uplink. Rewards are one-time; practice replays never create duplicate parts or modules.</p></details></aside></div>`;
function refreshLog(){$('#terminalLog').textContent=labLog.join('\n');$('#terminalLog').scrollTop=$('#terminalLog').scrollHeight;$('#terminalPrompt').textContent=lab.cwd+'>';}
$('#backToNetwork').onclick=ctx.onNetwork;refreshLog();$('#caseSelect').onchange=e=>{lab=newTerminal(Number(e.target.value));labLog=['RECOVERY ORDER '+(lab.id+1)+' / '+TERMINAL_CASES[lab.id].title,'Type help for commands.'];labHistory=[];labHistoryAt=0;renderTerminalPanel({...ctx,preferNext:false});};
$('#terminalForm').onsubmit=e=>{e.preventDefault();const input=$('#terminalCommand'),cmd=input.value.trim();if(!cmd)return;labHistory.push(cmd);labHistory=labHistory.slice(-50);labHistoryAt=labHistory.length;labLog.push(lab.cwd+'> '+cmd);const result=terminalCommand(lab,cmd);if(result.clear)labLog=[];labLog.push(result.output);labLog=labLog.slice(-80);input.value='';refreshLog();if(result.completed){if(!state.terminalCompleted.includes(lab.id)){if(!claimTerminal(state,lab.id))return;badges();save();updateHud();Array.from($('#caseSelect').options).forEach((option,i)=>{option.disabled=!terminalAvailable(state,i);option.textContent=(i+1)+'. '+TERMINAL_CASES[i].title+(state.terminalCompleted.includes(i)?' ✓':!terminalAvailable(state,i)?' · requires '+SECTORS[i].name+(i?' and case '+i:''):'');});document.querySelector("#caseCount").textContent=state.terminalCompleted.length+'/6 cases solved';document.querySelector("#caseSelect").selectedOptions[0].textContent=(lab.id+1)+'. '+job.title+' ✓';document.querySelector("#caseReward").textContent='Cache recovered. Replay for practice.';document.querySelector('#backToNetwork').textContent='Return to network · '+availableModules(state)+' modules available';toast('Recovered: '+job.reward+' components + 1 uplink module.');$('#caseFeedback').innerHTML='<div class="feedback">Server recovered. Components and an uplink module secured. Return to the network to install your equipment.</div>';}else $('#caseFeedback').innerHTML='<div class="feedback">Verified again. This mission’s cache is already secured.</div>';}input.focus();};
$('#terminalCommand').onkeydown=e=>{if(e.key==='ArrowUp'||e.key==='ArrowDown'){e.preventDefault();labHistoryAt=Math.max(0,Math.min(labHistory.length,labHistoryAt+(e.key==='ArrowUp'?-1:1)));e.target.value=labHistory[labHistoryAt]||'';}};
document.querySelectorAll('[data-insert-command]').forEach(b=>b.onclick=()=>{$('#terminalCommand').value=b.dataset.insertCommand;$('#terminalCommand').focus();});
$('#caseHint').onclick=()=>{$('#caseFeedback').innerHTML='<div class="feedback hint">'+esc(job.hint)+'</div>';};$('#resetCase').onclick=()=>{lab=newTerminal(lab.id);labLog=['Case restarted. Previously recovered caches stay collected.'];renderTerminalPanel({...ctx,preferNext:false});};
}
